arguments.script:
function ring(pts) {
  var a = 0, cx = 0, cy = 0;
  for (var i = 0; i < pts.length; i++) {
    var p = pts[i], q = pts[(i + 1) % pts.length];
    var c = p[0] * q[1] - q[0] * p[1];
    a += c; cx += (p[0] + q[0]) * c; cy += (p[1] + q[1]) * c;
  }
  return { a: a / 2, cx: cx, cy: cy };
}
function widget(project, params, ctx) {
  var items = [];
  var zh = ctx.language !== 'en';
  for (var s of project.spaces) {
    if (!s.shape || !s.shape.length) continue;
    var area = 0, best = null;
    for (var part of s.shape) {
      var r = ring(part.outer);
      var pa = Math.abs(r.a);
      for (var h of part.holes || []) pa -= Math.abs(ring(h).a);
      area += pa;
      if (!best || Math.abs(r.a) > Math.abs(best.a)) best = r;
    }
    if (!best || best.a === 0) continue;
    var at = [best.cx / (6 * best.a), best.cy / (6 * best.a)];
    var m2 = (area / 1e6).toFixed(params.decimals);
    var text = params.showName ? s.name + ' ' + m2 + ' m²' : m2 + ' m²';
    items.push({ type: 'label', at: at, text: text, level: s.level });
  }
  return items;
}
